using GodTreeXOwais.Core; namespace GodTreeXOwais.Runtime; public sealed class ValidationEngine{public IReadOnlyList<ValidationResult> Validate(string runDir){var a=Path.Combine(runDir,"artifacts");return new[]{new ValidationResult("artifacts",Directory.Exists(a)&&Directory.EnumerateFiles(a).Any(),"Artifacts exist"),new("events",File.Exists(Path.Combine(runDir,"events.jsonl")),"Event journal exists"),new("metadata",File.Exists(Path.Combine(runDir,"run.json")),"Run metadata exists")};}}